  SomList<BrowserRequirementEntry> get browserRequirements => SomList<BrowserRequirementEntry>(doc, '$path/BROREQ-BROW-LST', (d, p) => BrowserRequirementEntry(d, p), pattern: 'BROREQ-BROW-xxx');

