  /// Password Lifecycle.
  PasswordLifecyclePolicy get passwordLifecycle => PasswordLifecyclePolicy(doc, '$path/passwordLifecycle');

  /// Account Lockout and Throttling.
  AccountLockoutPolicy get accountLockout => AccountLockoutPolicy(doc, '$path/accountLockout');

  /// Credential Recovery.
